export const STAGES=['Saved','Applied','Interview','Offer','Closed'];
export const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
export function day(offset=0,hour=10){const d=new Date();d.setDate(d.getDate()+offset);d.setHours(hour,0,0,0);return d.toISOString()}
export function classify(subject='',body=''){
 const t=`${subject} ${body}`.toLowerCase();
 if(/unfortunately|not (be )?moving forward|other candidates|position has been filled/.test(t))return {category:'Update',confidence:'Rule match',reason:'Contains a rejection or closed-position phrase.'};
 if(/interview|schedule a call|meet with (our|the) team|availability for|recruiter screen/.test(t))return {category:'Interview',confidence:'Needs review',reason:'Contains an interview or scheduling phrase. Confirm the role, date and sender.'};
 if(/offer letter|pleased to offer|extend an offer/.test(t))return {category:'Offer',confidence:'Needs review',reason:'Contains an offer phrase; review the original message.'};
 if(/application|applied|resume|résumé|received your/.test(t))return {category:'Application',confidence:'Rule match',reason:'Contains an application-related phrase.'};
 return {category:'Other',confidence:'Uncertain',reason:'No career-related rule matched. Review manually.'};
}
export function conflicts(start,end,events,buffer=15){const a=Date.parse(start),b=Date.parse(end);if(!Number.isFinite(a)||!Number.isFinite(b)||b<=a)throw new Error('Choose a valid start and end time.');return events.filter(e=>e.busy!==false&&a<Date.parse(e.end)+buffer*60000&&b>Date.parse(e.start)-buffer*60000)}
export function alternatives(start,events,duration=30,buffer=15){const d=new Date(start);const result=[];for(let i=1;i<=48&&result.length<3;i++){const a=new Date(+d+i*30*60000);if(a.getHours()<9||a.getHours()>=17||a.getDay()===0||a.getDay()===6)continue;const b=new Date(+a+duration*60000);if(!conflicts(a,b,events,buffer).length)result.push({start:a.toISOString(),end:b.toISOString()})}return result}
export function safeURL(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:''}catch{return ''}}
export function escapeICS(s){return String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,')}
export function calendarFile(e){const dt=s=>new Date(s).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//AUTO WORK//Career Assistant//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT',`UID:${uid()}@auto-work.local`,`DTSTAMP:${dt(new Date())}`,`DTSTART:${dt(e.start)}`,`DTEND:${dt(e.end)}`,`SUMMARY:${escapeICS(e.title)}`,`DESCRIPTION:${escapeICS('Manually exported from AUTO WORK. '+(e.description||''))}`,'END:VEVENT','END:VCALENDAR'];return lines.map(line=>{let chunks=[],s='';let bytes=0;for(const c of line){let n=new TextEncoder().encode(c).length;if(bytes+n>73){chunks.push(s);s=' '+c;bytes=n+1}else{s+=c;bytes+=n}}chunks.push(s);return chunks.join('\r\n')}).join('\r\n')+'\r\n'}
export function validateProfile(input){const fields=['name','email','education','target','location','skills','experience','about','fillerURL'];const p={};for(const k of fields)p[k]=String(input[k]??'').slice(0,k==='experience'||k==='about'?12000:2000);if(p.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.email))throw new Error('Enter a valid email address.');if(p.fillerURL&&!safeURL(p.fillerURL))throw new Error('RESUME FILLER URL must begin with http or https.');return p}
export function profileImport(input){const p=input.profile||input;return validateProfile({name:p.name||[p.firstName,p.lastName].filter(Boolean).join(' '),email:p.email,education:p.education,target:p.target||p.targetRole,location:p.location,skills:Array.isArray(p.skills)?p.skills.join(', '):p.skills,experience:p.experience,about:p.about,fillerURL:p.fillerURL})}
export function briefFor(app,profile,sources=[]){const skills=(profile.skills||'').split(/[,\n]/).map(s=>s.trim()).filter(Boolean);const text=`${app.role} ${app.description||''}`.toLowerCase();const matched=skills.filter(s=>text.includes(s.toLowerCase()));return {intro:`${profile.name?`I’m ${profile.name}`:'[Add your name in About me]'}${profile.education?`, studying at ${profile.education}`:''}. I’m interested in ${app.role} at ${app.company}. ${profile.about||'[Add a short introduction and what interests you about this work.]'}`,matched,missing:!profile.experience?'Add one real project or experience before practicing evidence-based answers.':'Choose one example from your saved experience and verify every claim.',experience:profile.experience,questions:['Tell me about yourself and why this role interests you.',`How would you measure success for a ${app.role.toLowerCase()} project?`,'Walk me through a campaign or project: goal, your contribution, result, and what you learned.','How would you adapt a message for two different audiences?','Tell me about feedback you received and how you used it.'],ask:['What would a successful first month look like?','How does the team measure campaign performance?','Who would I collaborate with most closely?'],sources:sources.filter(s=>s.appId===app.id),label:'Template preparation • not AI research'};}
export function seed(demo=true){const profile={name:'',email:'',education:'UC Berkeley',target:'Marketing internships',location:'',skills:'',experience:'',about:'',fillerURL:''};const s={version:1,profile,apps:[],messages:[],events:[],approvals:[],reminders:[],sources:[],notes:{},activity:[],settings:{buffer:15,autoTriage:false},demo};if(!demo)return s;
 s.apps=[{id:'a1',company:'Arc & Loom',role:'Social Media Marketing Intern',stage:'Interview',description:'Short-form content, social media strategy, campaign reporting and audience research.',color:'peach',deadline:day(3),url:'',notes:'Fictional example. Add your real application details.'},{id:'a2',company:'Northstar Studio',role:'Brand Marketing Intern',stage:'Applied',description:'Brand storytelling, creative briefs and campaign analysis.',color:'lavender',deadline:day(7),url:'',notes:''},{id:'a3',company:'Fieldwork',role:'Growth Marketing Intern',stage:'Saved',description:'Experiment design, email campaigns and performance reporting.',color:'green',deadline:day(5),url:'',notes:''},{id:'a4',company:'Monday Market',role:'Content & Community Intern',stage:'Applied',description:'Community engagement and editorial planning.',color:'yellow',deadline:day(4),url:'',notes:''}];
 s.messages=[{id:'m1',from:'Recruiting · Arc & Loom',subject:'Let’s talk — Social Media Marketing Intern',body:'Thanks for applying! We would love to invite you to an interview with our marketing team. Could you share your availability? This is a fictional sample message.',received:day(0,9),category:'Interview',reason:'Contains “interview” and “availability”. Confirm all details before scheduling.',appId:'a1',processed:true},{id:'m2',from:'Northstar Studio',subject:'We received your application',body:'Thank you for your application for Brand Marketing Intern. Our team will review it soon. Fictional sample.',received:day(0,8),category:'Application',processed:true},{id:'m3',from:'Monday Market',subject:'A quick update on your application',body:'Our hiring team is reviewing applications this week. We will be in touch. Fictional sample.',received:day(-1,14),category:'Application',processed:true}];
 s.events=[{id:'e1',title:'Arc & Loom · interview (sample)',start:day(1,14),end:new Date(Date.parse(day(1,14))+30*60000).toISOString(),type:'Interview',appId:'a1',busy:true},{id:'e2',title:'Class / study block (sample)',start:day(1,10),end:day(1,12),type:'Personal',busy:true}];
 s.approvals=[{id:'p1',type:'reply',title:'Review your interview reply',appId:'a1',messageId:'m1',body:'Hi team,\n\nThank you for the invitation! I’m excited to learn more about the Social Media Marketing Intern role. Could you share a few available times and the interview format?\n\nBest,\n[Your name]',status:'pending',created:day(0,9)}];
 s.reminders=[{id:'r1',title:'Prepare 2 examples for Arc & Loom',due:day(1,9),done:false,appId:'a1'},{id:'r2',title:'Review Fieldwork application',due:day(2,10),done:false,appId:'a3'}];s.activity=[{id:'log1',at:day(0,9),text:'Demo loaded. All companies, messages and events are fictional.',kind:'system'}];return s}
export function triage(state){let count=0;for(const m of state.messages){if(m.processed)continue;Object.assign(m,classify(m.subject,m.body),{processed:true});count++;if(m.category==='Interview'&&!state.approvals.some(a=>a.messageId===m.id)){state.approvals.push({id:uid(),type:'reply',messageId:m.id,appId:m.appId||'',title:`Review reply: ${m.subject}`,body:`Hello,\n\nThank you for the interview invitation. I would be happy to learn more. Could you confirm the role, interview format, time zone and available times?\n\nBest,\n${state.profile.name||'[Your name]'}`,status:'pending',created:new Date().toISOString()})}}return count}
